/* =====================================================================
   engine.localize.js  —  Engine.Localize   (blueprint §48)

   The localization engine. It gives every generated app a real i18n
   substrate — no hard-coded user-facing strings, a source catalogue, a
   tiny runtime, RTL awareness, and a pseudo-locale for layout testing —
   and then audits coverage as evidence.

     catalog(spec)   -> { 'public/i18n/en.json', 'public/i18n/<locale>.json' …,
                          'public/i18n/pseudo.json' }
     runtime()       -> the 'public/i18n.js' source (t(), plural, dir, switch)
     files(spec)     -> catalogue + runtime as one { path: content } map
     analyze()       -> scans /public + /public/i18n/*.json, writes
                        .sovereign/localization-findings.json:
                        untagged visible strings, missing keys, per-locale
                        coverage, interpolation-var mismatches, dir wiring
     load()          -> the findings or null

   The generated frontend still renders English straight from the HTML
   (so it works with JS disabled); the runtime swaps `[data-i18n]` /
   `[data-i18n-attr]` nodes and `window.t()` calls for the active locale.
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var S = function () { return Engine.Sovereign; };

  var RTL = { ar: 1, he: 1, fa: 1, ur: 1, ps: 1, sd: 1, dv: 1, ckb: 1, yi: 1 };

  function titleCase(s) {
    return String(s || '').replace(/([A-Z])/g, ' $1').replace(/[_-]+/g, ' ')
      .replace(/\s+/g, ' ').trim().replace(/^./, function (c) { return c.toUpperCase(); });
  }

  // the universal UI strings every generated app uses
  function baseCatalog(spec) {
    var c = {
      'app.title': (spec && spec.name) ? spec.name : 'App',
      'app.skipToContent': 'Skip to content',
      'auth.heading': 'Sign in',
      'auth.email': 'Email',
      'auth.password': 'Password',
      'auth.signIn': 'Sign in',
      'auth.register': 'Create account',
      'auth.signOut': 'Sign out',
      'auth.signedInAs': 'Signed in as {email}',
      'auth.error': 'Sign in failed',
      'list.loading': 'Loading…',
      'list.empty': 'Nothing yet',
      'list.error': 'Could not load',
      'list.count': '{n, plural, one {# item} other {# items}}',
      'action.add': 'Add {entity}',
      'action.delete': 'Delete',
      'action.save': 'Save',
      'form.required': 'This field is required',
      'form.saveError': 'Could not save'
    };
    ((spec && spec.entities) || []).forEach(function (e) {
      if (['user', 'session', 'job'].indexOf(e.name) >= 0) return;
      c['entity.' + e.name] = titleCase(e.name);
      (e.fields || []).forEach(function (f) {
        if (f.type === 'id' || (f.type === 'ref' && f.ref === 'user')) return;
        c['field.' + e.name + '.' + f.name] = titleCase(f.name) + (f.type === 'ref' ? ' (id)' : '');
      });
    });
    return c;
  }

  var ACCENT = { a: 'á', e: 'é', i: 'í', o: 'ó', u: 'ú',
    A: 'Á', E: 'É', I: 'Í', O: 'Ó', U: 'Ú',
    n: 'ñ', c: 'ç', s: 'š', y: 'ý' };

  // deterministic accented pseudo-localisation + ~30% padding (surfaces
  // truncation and un-tagged strings at a glance). Placeholders are kept intact.
  function pseudo(str) {
    var body = String(str).split(/(\{[^}]+\})/).map(function (seg) {
      if (seg.charAt(0) === '{') return seg;
      return seg.replace(/[aeiouAEIOUncsy]/g, function (ch) { return ACCENT[ch] || ch; });
    }).join('');
    var bare = body.replace(/\{[^}]+\}/g, '');
    var pad = new Array(Math.max(2, Math.round(bare.length * 0.3)) + 1).join('·');
    return '⟦' + body + ' ' + pad + '⟧';
  }

  function locales(spec) {
    var list = (spec && (spec.locales || spec.languages)) || [];
    return Array.isArray(list) ? list.filter(function (l) { return l && l !== 'en'; }) : [];
  }

  function catalog(spec) {
    var en = baseCatalog(spec);
    var out = { 'public/i18n/en.json': JSON.stringify(en, null, 2) + '\n' };
    // empty (untranslated) stubs for every requested locale — keys present,
    // values empty so the runtime falls back to English and analyze() reports
    // the coverage gap honestly.
    locales(spec).forEach(function (loc) {
      var stub = {};
      Object.keys(en).forEach(function (k) { stub[k] = ''; });
      out['public/i18n/' + loc + '.json'] = JSON.stringify(stub, null, 2) + '\n';
    });
    var ps = {};
    Object.keys(en).forEach(function (k) { ps[k] = pseudo(en[k]); });
    out['public/i18n/pseudo.json'] = JSON.stringify(ps, null, 2) + '\n';
    return out;
  }

  function runtime() {
    return [
      "'use strict';",
      "// generated by CodeSovereign Engine.Localize (blueprint 48) — dependency-free i18n runtime",
      "(function () {",
      "  var RTL = " + JSON.stringify(RTL) + ";",
      "  var dict = {}, fallback = {}, current = 'en';",
      "  function icu(str, vars) {",
      "    vars = vars || {};",
      "    str = String(str).replace(/\\{\\s*(\\w+)\\s*,\\s*plural\\s*,\\s*((?:[^{}]*\\{[^{}]*\\})*[^{}]*)\\}/g, function (_, name, body) {",
      "      var n = Number(vars[name]);",
      "      var forms = {};",
      "      body.replace(/(one|other|zero|=\\d+)\\s*\\{([^}]*)\\}/g, function (__, sel, txt) { forms[sel] = txt; return ''; });",
      "      var pick = forms['=' + n] || (n === 1 ? forms.one : null) || (n === 0 ? forms.zero : null) || forms.other || '';",
      "      return pick.replace(/#/g, String(n));",
      "    });",
      "    return str.replace(/\\{(\\w+)\\}/g, function (m, k) { return (k in vars) ? String(vars[k]) : m; });",
      "  }",
      "  function t(key, vars) {",
      "    var s = (key in dict) ? dict[key] : null;",
      "    if (s == null || s === '') s = (key in fallback) ? fallback[key] : key;",
      "    return icu(s, vars);",
      "  }",
      "  function dir(loc) { return RTL[String(loc || current).split('-')[0]] ? 'rtl' : 'ltr'; }",
      "  function apply(root) {",
      "    root = root || document;",
      "    root.querySelectorAll('[data-i18n]').forEach(function (el) {",
      "      if (el.children.length) return;  // never clobber a node that wraps elements",
      "      var v = {}; try { v = JSON.parse(el.getAttribute('data-i18n-vars') || '{}'); } catch (e) {}",
      "      el.textContent = t(el.getAttribute('data-i18n'), v);",
      "    });",
      "    root.querySelectorAll('[data-i18n-attr]').forEach(function (el) {",
      "      el.getAttribute('data-i18n-attr').split(',').forEach(function (pair) {",
      "        var kv = pair.split(':'); if (kv.length === 2) el.setAttribute(kv[0].trim(), t(kv[1].trim()));",
      "      });",
      "    });",
      "  }",
      "  async function load(loc) {",
      "    if (!Object.keys(fallback).length) { try { fallback = await fetch('i18n/en.json').then(function (r) { return r.json(); }); } catch (e) { fallback = {}; } }",
      "    if (loc && loc !== 'en') { try { dict = await fetch('i18n/' + loc + '.json').then(function (r) { return r.json(); }); } catch (e) { dict = {}; } }",
      "    else dict = fallback;",
      "    current = loc || 'en';",
      "    try { localStorage.setItem('lang', current); } catch (e) {}",
      "    var html = document.documentElement;",
      "    html.setAttribute('lang', current); html.setAttribute('dir', dir(current));",
      "    apply();",
      "  }",
      "  var initial = 'en';",
      "  try { initial = new URLSearchParams(location.search).get('lang') || localStorage.getItem('lang') || String(navigator.language || 'en').slice(0, 2) || 'en'; } catch (e) {}",
      "  window.i18n = { t: t, dir: dir, apply: apply, load: load, get locale() { return current; } };",
      "  window.t = t;",
      "  if (document.readyState !== 'loading') load(initial); else document.addEventListener('DOMContentLoaded', function () { load(initial); });",
      "})();",
      ""
    ].join('\n');
  }

  function files(spec) {
    var out = catalog(spec);
    out['public/i18n.js'] = runtime();
    return out;
  }

  /* ---------------- audit ---------------- */
  function fread(p) { try { return (Engine.FS && Engine.FS.read(p)) || ''; } catch (_) { return ''; } }
  function fjson(p) { try { var r = fread(p); return r ? JSON.parse(r) : null; } catch (_) { return null; } }
  function fexists(p) { try { return !!(Engine.FS && Engine.FS.isFile(p)); } catch (_) { return false; } }
  function listFiles(re) {
    try {
      return Object.keys(Engine.FS._data || {}).filter(function (p) {
        return Engine.FS.isFile(p) && re.test(p) && !/\/(node_modules|\.sovereign|dist)\//.test(p);
      });
    } catch (_) { return []; }
  }

  function varsIn(str) {
    var out = {};
    String(str).replace(/\{(\w+)(?:\s*,)?/g, function (_, n) {
      if (['plural', 'one', 'other', 'zero'].indexOf(n) < 0) out[n] = 1;
      return '';
    });
    return Object.keys(out).sort();
  }

  // visible text nodes in HTML that are NOT routed through i18n
  function untaggedStrings(html) {
    var out = [];
    var stripped = html
      .replace(/<!--[\s\S]*?-->/g, '')
      .replace(/<script\b[\s\S]*?<\/script>/gi, '')
      .replace(/<style\b[\s\S]*?<\/style>/gi, '')
      .replace(/<(title|option)\b[\s\S]*?<\/\1>/gi, '');
    var re = /<([a-z0-9]+)((?:\s+[^>]*)?)>\s*([^<>{}\n][^<>]*?)\s*<\/\1>/gi;
    var m;
    while ((m = re.exec(stripped))) {
      var attrs = m[2] || '', text = (m[3] || '').trim();
      if (!text || text.length < 2) continue;
      if (/^[\s\d.,:;!?%$#@/\\|()[\]•·—–-]+$/.test(text)) continue;
      if (/data-i18n/.test(attrs)) continue;
      out.push(text.slice(0, 60));
    }
    return out;
  }

  function analyze() {
    var contract = null;
    try { contract = Engine.Contract && Engine.Contract.load && Engine.Contract.load(); } catch (_) {}
    var requested = !!(contract && JSON.stringify(contract).match(/localiz|internationaliz|\bi18n\b|multi[- ]?language|translat/i));

    var en = fjson('/public/i18n/en.json');
    var htmlFiles = listFiles(/\/public\/[^/]+\.html$/);
    var findings = [];

    if (!en && !htmlFiles.length) {
      var none = { generatedAt: Date.now(), present: false, requested: requested, note: 'no frontend / i18n catalogue in the workspace', score: 100, healthy: true };
      if (S()) S().write('localization-findings.json', none);
      return none;
    }

    // 1) hard-coded visible strings in the shipped HTML
    var leaks = [];
    htmlFiles.forEach(function (p) { untaggedStrings(fread(p)).forEach(function (s) { leaks.push({ file: p, text: s }); }); });
    if (leaks.length) findings.push({ rule: 'hardcoded-string', impact: requested ? 'serious' : 'moderate', count: leaks.length, sample: leaks.slice(0, 8) });

    // 2) window.t() / data-i18n keys missing from en.json
    var used = {};
    listFiles(/\/public\/[^/]+\.(html|js)$/).forEach(function (p) {
      if (/\/i18n\.js$/.test(p)) return;
      var src = fread(p);
      (src.match(/\bt\(\s*['"]([a-zA-Z0-9_.]+)['"]/g) || []).forEach(function (mm) { used[mm.replace(/.*['"]([^'"]+)['"].*/, '$1')] = 1; });
      (src.match(/data-i18n="([a-zA-Z0-9_.]+)"/g) || []).forEach(function (mm) { used[mm.replace(/.*"([^"]+)".*/, '$1')] = 1; });
    });
    var missingKeys = en ? Object.keys(used).filter(function (k) { return !(k in en); }) : Object.keys(used);
    if (missingKeys.length) findings.push({ rule: 'missing-key', impact: 'serious', keys: missingKeys.slice(0, 20) });

    // 3) per-locale coverage + interpolation parity
    var localeCoverage = {};
    listFiles(/\/public\/i18n\/[a-z-]+\.json$/).forEach(function (p) {
      var loc = p.replace(/.*\/([a-z-]+)\.json$/, '$1');
      if (loc === 'en') return;
      var tr = fjson(p) || {};
      var keys = Object.keys(en || tr);
      var translated = 0;
      var varMismatch = [];
      keys.forEach(function (k) {
        var v = tr[k];
        if (v != null && v !== '') {
          translated++;
          if (en && varsIn(en[k]).join(',') !== varsIn(v).join(',')) varMismatch.push(k);
        }
      });
      localeCoverage[loc] = { translated: translated, total: keys.length, pct: keys.length ? Math.round(translated / keys.length * 100) : 100, dir: RTL[loc.split('-')[0]] ? 'rtl' : 'ltr' };
      if (varMismatch.length) findings.push({ rule: 'interpolation-mismatch', impact: 'serious', locale: loc, keys: varMismatch.slice(0, 12) });
      if (loc !== 'pseudo' && translated < keys.length) findings.push({ rule: 'incomplete-locale', impact: requested ? 'serious' : 'minor', locale: loc, translated: translated, total: keys.length });
    });

    // 3b) the contract asked for localization but no target locale was generated
    if (requested && Object.keys(localeCoverage).filter(function (l) { return l !== 'pseudo'; }).length === 0) {
      findings.push({ rule: 'no-locales', impact: 'serious', detail: 'the contract asks for localization but only English + the pseudo-locale exist — add locale catalogues under public/i18n/' });
    }

    // 4) runtime present + RTL wiring
    if (!fexists('/public/i18n.js')) findings.push({ rule: 'no-runtime', impact: 'moderate', detail: 'i18n.js runtime is not in /public — [data-i18n] nodes will not be localised' });
    else if (!/setAttribute\(['"]dir['"]/.test(fread('/public/i18n.js'))) findings.push({ rule: 'no-rtl', impact: 'moderate', detail: 'runtime does not set <html dir> — RTL locales render LTR' });

    var byImpact = findings.reduce(function (m, f) { m[f.impact] = (m[f.impact] || 0) + 1; return m; }, {});
    var score = Math.max(0, 100 - (byImpact.serious || 0) * 15 - (byImpact.moderate || 0) * 6 - (byImpact.minor || 0) * 2);
    var report = {
      generatedAt: Date.now(), present: true, requested: requested,
      catalogueKeys: en ? Object.keys(en).length : 0,
      locales: localeCoverage,
      leaks: leaks.length,
      findings: findings, byImpact: byImpact, score: score,
      healthy: requested ? !(byImpact.serious) : true
    };
    if (S()) {
      S().write('localization-findings.json', report);
      S().write('localization-report.md',
        '# Localization\n\n_Generated ' + new Date(report.generatedAt).toISOString() + '_\n\n' +
        '**Score ' + score + '/100** · ' + report.catalogueKeys + ' catalogue keys · ' +
        Object.keys(localeCoverage).length + ' extra locale(s)' + (requested ? ' · **requested by the contract**' : '') + '\n\n' +
        (Object.keys(localeCoverage).length
          ? '| Locale | Coverage | Dir |\n|---|---|---|\n' + Object.keys(localeCoverage).map(function (l) {
            return '| ' + l + ' | ' + localeCoverage[l].pct + '% (' + localeCoverage[l].translated + '/' + localeCoverage[l].total + ') | ' + localeCoverage[l].dir + ' |';
          }).join('\n') + '\n\n'
          : '') +
        (findings.length ? findings.map(function (f) { return '- **' + f.rule + '** (' + f.impact + ')' + (f.locale ? ' — ' + f.locale : '') + (f.count ? ' x' + f.count : ''); }).join('\n') + '\n' : '_No issues._\n'));
    }
    return report;
  }

  function load() {
    try { var v = S() && S().read('localization-findings.json'); return (v && typeof v === 'object') ? v : null; } catch (_) { return null; }
  }

  Engine.Localize = { RTL: RTL, catalog: catalog, runtime: runtime, files: files, analyze: analyze, load: load, _pseudo: pseudo, _titleCase: titleCase };
  console.info('[Localize] localization engine ready — Engine.Localize');
})();
